// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract InvMutTest is Test {
    EBU c;
    function setUp() public { c = new EBU(); }

    function testFuzz_property(address from, address to, uint256 amount, uint256 n) public {
        n = bound(n, 2, 8);
        address[] memory tos = new address[](n);
        uint256[] memory vals = new uint256[](n);
        for (uint256 i = 0; i < n; i++) {
            tos[i] = to;
            vals[i] = amount;
        }
        Recorder rec = new Recorder();
        (bool ok, ) = address(c).call(
            abi.encodeWithSignature("transfer(address,address,address[],uint256[])", from, address(rec), tos, vals)
        );
        assertTrue(ok && rec.count() == n);
    }
}

contract Recorder {
    uint256 public count;
    function transferFrom(address, address, uint256) external returns (bool) {
        count++;
        return true;
    }
}
